class MuseumClimateController
{
public:
    void prepareEveningExhibit()
    {
        ExhibitBrief eveningBrief("eveningBrief");

        {
            SecurityOverride securityOverride("securityOverride");

            {
                CalibrationConsole calibrationConsole("calibrationConsole");
                calibrateDisplay(calibrationConsole, eveningBrief);
            }

            reviewEvacuationLights(securityOverride, eveningBrief);
        }

        {
            ProjectionRig projectionRig("projectionRig");
            renderProjectionPreview(projectionRig, eveningBrief);
        }

        announceExhibitReady(eveningBrief);
    }
};
